var s=`1399-green-lipped-mussels`;var n=`world-1399`;var t=`NZ`;var a=`oceania`;var r=4;var d=26;var l={en:`Green-Lipped Mussels`,ua:`Зеленогубі мідії`};var g={en:`Green-Lipped Mussels is a dish from New Zealand featuring garlic, green-lipped mussel, lemon juice, parsley. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Зеленогубі мідії, страва кухні країни Нова Зеландія з такими основними складниками: часник, зеленогуба мідія, лимонний сік, петрушка. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var u=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 8 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 8 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:8,i:[[`garlic`,5,`clove`],[`unsalted-butter`,70,`g`],[`dry-white-wine`,160,`ml`]]},{en:`Steam scrubbed green-lipped mussels under a tight lid until shells open; discard cracked shells before cooking and any unopened shells afterward.`,ua:`Готуйте очищені зеленогубі мідії під щільною кришкою до розкриття мушель; пошкоджені відкиньте до приготування, нерозкриті, після.`,t:[`steaming`],m:12,i:[[`green-lipped-mussel`,1200,`g`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:3,i:[[`ground-black-pepper`,4,`g`],[`lemon-juice`,75,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,28,`g`]]}];var o={slug:s,id:n,country:`NZ`,region:a,servings:4,minutes:26,title:l,text:g,steps:u};export{t as country,o as default,n as id,d as minutes,a as region,r as servings,s as slug,u as steps,g as text,l as title};